)
values
  ('4d4604d0-fe19-51cb-8a3f-0291d0a72e44'::uuid, 'What is one small change that would improve your morning? State the change and one reason.', true, 'practice', 'beginner', 30, null, false),
  ('b927c0b7-05ae-508f-bba3-763e71cc33d1'::uuid, 'Describe a place where you like to spend time. Include two details someone could picture.', true, 'practice', 'beginner', 30, null, false),
  ('4b977408-fab6-50cf-bd42-1eae5e2a5ba2'::uuid, 'Explain how you prepare a simple meal, drink, or snack from start to finish.', true, 'practice', 'beginner', 30, null, false),
  ('a66de8e5-5c12-5778-8456-a3fc4b5e2446'::uuid, 'Choose a season you enjoy and explain one reason it works well for you.', true, 'practice', 'beginner', 30, null, false),
  ('b2e65c7c-7ac8-5f4b-aed7-d5d5d651730f'::uuid, 'Tell a short story about a plan that changed unexpectedly. Make the order of events clear.', true, 'practice', 'beginner', 45, null, false),
  ('2205350b-d88a-5b0b-805c-6cc1a18fe25a'::uuid, 'Summarize a book, show, game, or event for someone who knows nothing about it.', true, 'practice', 'beginner', 45, null, false),
  ('6303ce9d-c696-58de-a171-f68ab6daa694'::uuid, 'Compare spending a free afternoon indoors and outdoors. Mention one benefit of each.', true, 'practice', 'beginner', 45, null, false),
  ('f5b74854-aa5d-5afe-afd1-0eafdf8500f1'::uuid, 'Would you rather plan a day ahead or decide as you go? State your preference and why.', true, 'practice', 'beginner', 45, null, false),
  ('7476624d-6ddf-5096-9831-1d09430f6e80'::uuid, 'Explain one habit that helps your day, then end with one concise takeaway.', true, 'practice', 'beginner', 45, null, false),
  ('52a7eb6f-547f-5b74-9639-5f31a9e14ccf'::uuid, 'A friend has one free hour in your area. Recommend how to use it, explain why, and end with a clear next step.', true, 'practice', 'beginner', 60, null, false),
  ('a94b7a52-dce7-5993-97b6-648c8b175293'::uuid, 'Explain a hobby, routine, or tool you know well to someone encountering it for the first time.', true, 'practice', 'intermediate', 45, null, false),
  ('587aa5c4-c153-5d22-a97a-f5bcd3b22628'::uuid, 'What makes a shared space pleasant to use? Give a clear answer with three parts.', true, 'practice', 'intermediate', 45, null, false),
  ('1db55afa-1b2a-5ad2-b627-b67ef44bcfc7'::uuid, 'Should people keep one evening each week free of plans? State your view and support it with an example.', true, 'practice', 'intermediate', 45, null, false),
  ('622fe79c-4238-530e-bd19-aba07bbfc080'::uuid, 'Explain online maps to someone who has only used paper maps. Choose details that help that listener.', true, 'practice', 'intermediate', 45, null, false),
  ('84da0ba0-aec5-5836-8923-cb3fcffa190d'::uuid, 'Describe a useful habit, then answer this follow-up: What makes it difficult to maintain?', true, 'practice', 'intermediate', 45, null, false),
  ('3b2e18d7-038d-5a7a-b66f-6c64dfc498b7'::uuid, 'People often say a place has a good atmosphere. Explain exactly what that means to you.', true, 'practice', 'intermediate', 45, null, false),
  ('4f757680-24b7-55ee-9413-77f1a45a8599'::uuid, 'Explain how changing a daily routine can affect the rest of the day.', true, 'practice', 'intermediate', 45, null, false),
  ('d0da3070-0b71-523f-8b1c-ec6f804acc85'::uuid, 'Discuss the benefits of planning ahead and staying flexible, then say when each works better.', true, 'practice', 'intermediate', 60, null, false),
  ('0ee553d7-5931-55a3-a312-73cd15c607a8'::uuid, 'In 45 seconds, explain what makes a recommendation trustworthy.', true, 'practice', 'intermediate', 45, null, false),
  ('c1adb0e4-4915-59de-b324-854b6f974be0'::uuid, 'Explain whether a familiar shared routine should change. Give context, compare two effects, use an example, and close with your recommendation.', true, 'practice', 'intermediate', 60, null, false),
  ('1fc82d35-6704-540b-b782-aa1b8d50a570'::uuid, 'What does convenience mean in everyday life? Define the part of the idea you will address before giving your view.', true, 'practice', 'advanced', 60, null, false),
  ('39d995ad-c5cf-5bfd-843d-ed6b859e6975'::uuid, 'Bring together time, cost, and enjoyment to explain how you choose between two ways to spend a day.', true, 'practice', 'advanced', 60, null, false),
  ('9b7b52b5-a8b9-53c9-99b2-2d0c0d5a3409'::uuid, 'Is it better to keep routines consistent? Make a case that includes when your answer might not apply.', true, 'practice', 'advanced', 60, null, false),
  ('818ed8ae-ea25-51c7-b9bf-e90a691cae2d'::uuid, 'Recommend reducing notifications, then respond to someone who says they need to stay reachable.', true, 'practice', 'advanced', 60, null, false),
  ('5e87a394-6035-55f5-912f-0d25acc87d66'::uuid, 'You can improve only one part of a shared community space this month. Choose a priority and justify it.', true, 'practice', 'advanced', 60, null, false),
  ('cb6bfa56-3e1f-5812-994c-611b1fd4693b'::uuid, 'Explain the tradeoffs between owning fewer things and keeping items for possible future use.', true, 'practice', 'advanced', 60, null, false),
  ('52865d99-2167-5bce-868c-9e22ad0833bc'::uuid, 'Begin by discussing whether busy days are productive, then reframe the question around what a useful day accomplishes.', true, 'practice', 'advanced', 60, null, false),
  ('7edd637d-96f5-5527-9432-80610278eab5'::uuid, 'Summarize the case for and against a four-day event schedule, then give your conclusion in one sentence.', true, 'practice', 'advanced', 60, null, false),
  ('5652c3ce-adf8-57ab-9e68-ecc373a50f2e'::uuid, 'Tell a short story about changing your mind, explain what evidence mattered, and state the conclusion you reached.', true, 'practice', 'advanced', 60, null, false),
  ('e336b9c0-9ae1-53e3-bace-72dcf9263bbd'::uuid, 'A group must choose between a familiar plan and an uncertain new option. Frame the decision, explain the tradeoffs, address one objection, and recommend a next step.', true, 'practice', 'advanced', 60, null, false),
  ('a7cc61d3-17a1-511c-b374-522ad4d22b2e'::uuid, 'Tell me about yourself and the experiences or interests that bring you to this opportunity.', true, 'interview', 'beginner', 45, null, false),
