  ('150d3218-3823-52e9-9aab-bcdedcecd828'::uuid, 'Close a conversation about where and when to meet so both people know the plan.', true, 'conversation', 'beginner', 30, null, false),
  ('630730eb-9ec7-5ad9-ba9f-0ae2797c550e'::uuid, 'A friend wants to change a weekend plan. Respond, ask one useful question, state your preference, and close with a next step.', true, 'conversation', 'beginner', 60, null, false),
  ('b1641cfb-d50e-5c6c-a7af-a959d32bc4a9'::uuid, 'A friend prefers a plan you would not choose. Explore what matters to them before sharing your view.', true, 'conversation', 'intermediate', 45, null, false),
  ('d6e9f951-5383-5128-8bb7-e71d95b97882'::uuid, 'Someone thinks you agreed to organize the whole activity, but you agreed only to one part. Clarify the misunderstanding.', true, 'conversation', 'intermediate', 45, null, false),
  ('5725b326-272a-5490-9c1b-b56bac7698ec'::uuid, 'A group plan may leave one person without a practical way to participate. Raise the concern.', true, 'conversation', 'intermediate', 45, null, false),
  ('2808f5fa-9448-5bcd-a5d2-bd9fa7756edd'::uuid, 'A friend often asks for help late at night. Set a clear boundary and offer an alternative.', true, 'conversation', 'intermediate', 45, null, false),
  ('0c6b7ccf-8e0c-5f15-b642-1a3316c4798c'::uuid, 'Explain why you are leaving a recurring activity even though you have enjoyed parts of it.', true, 'conversation', 'intermediate', 45, null, false),
  ('a95c026c-5def-5f0a-a6a8-e462eb027cba'::uuid, 'You are explaining a concern when someone interrupts with a different issue. Respond and return to your point.', true, 'conversation', 'intermediate', 45, null, false),
  ('308c29f4-29fd-5a89-b572-ca87f06ad882'::uuid, 'A planning conversation has moved far from the decision you need to make. Redirect it to the next step.', true, 'conversation', 'intermediate', 45, null, false),
  ('824f102e-37bd-5427-bbea-9fb0c9494c56'::uuid, 'Tell a group member that interruptions make discussion difficult, then respond when they say you sometimes speak too long.', true, 'conversation', 'intermediate', 60, null, false),
  ('63cb9944-6463-5569-ae70-47a4f8493af3'::uuid, 'You and a friend still disagree about a plan. Propose a practical next step that does not require full agreement.', true, 'conversation', 'intermediate', 45, null, false),
  ('a86e5795-424a-5a11-a422-f4ba32f028d2'::uuid, 'A shared plan keeps changing and both people are frustrated. Clarify the issue, hear the other view, state a boundary, and propose a next step.', true, 'conversation', 'intermediate', 60, null, false),
  ('721e3667-31ad-5dfe-969e-feafed8a1815'::uuid, 'Two people need different things from the same plan: predictability and flexibility. Guide the conversation toward an arrangement.', true, 'conversation', 'advanced', 60, null, false),
  ('dff94412-6fd3-53b3-af16-e8dd77712a8d'::uuid, 'Tell a friend that a recurring joke about you has become uncomfortable and explain what you want to change.', true, 'conversation', 'advanced', 60, null, false),
  ('64393e77-cd2a-518f-9d37-6cfc2ed2c9ee'::uuid, 'You raise a concern and the other person says you are blaming them for everything. Respond without escalating.', true, 'conversation', 'advanced', 60, null, false),
  ('7e5e3d2f-7ef3-58af-b0a8-e83744e91e38'::uuid, 'A discussion about shared responsibilities becomes tense. De-escalate it and restate the decision that still needs attention.', true, 'conversation', 'advanced', 60, null, false),
  ('b2f3b47b-f142-5950-9d2c-6513f0fc71f0'::uuid, 'Someone says your recent choices have been difficult but gives no example. Ask questions that clarify the concern.', true, 'conversation', 'advanced', 60, null, false),
  ('0c0e91f2-0cfb-54eb-b2c8-ba8b633fbdd1'::uuid, 'You cannot keep changing plans on the same day, but a friend needs some flexibility. Negotiate a boundary.', true, 'conversation', 'advanced', 60, null, false),
  ('8ed01fa7-9a4f-50ac-8928-71a4b40da74f'::uuid, 'You realize your comment sounded dismissive during a difficult conversation. Repair it and continue the discussion.', true, 'conversation', 'advanced', 60, null, false),
  ('a243c8f6-b613-5562-b384-2e38f536d784'::uuid, 'You agree with a friend about the goal but disagree about the timing and method. Explain the distinction.', true, 'conversation', 'advanced', 60, null, false),
  ('a3796e7c-165f-5320-b70f-40bb814fc39d'::uuid, 'You and another person still disagree after a careful discussion. Close with what is decided and what remains unresolved.', true, 'conversation', 'advanced', 60, null, false),
  ('83ef0035-40cb-5ac3-8ab6-2c0a237e2df6'::uuid, 'A friend is upset about a repeated change in plans. Explore the concern, respond to defensiveness, negotiate a boundary, and close even if you do not fully agree.', true, 'conversation', 'advanced', 60, null, false)
on conflict (id) do update set
  text = excluded.text,
  active = excluded.active,
  mode = excluded.mode,
  difficulty = excluded.difficulty,
  target_duration_seconds = excluded.target_duration_seconds,
  collection_id = excluded.collection_id,
  free_practice_visible = excluded.free_practice_visible;

insert into public.practice_lessons (
  id, chapter_id, slug, title, skill_focus, position, checkpoint, prompt_id, active
)
values
  ('89d981d6-9c51-53da-8b4b-f98fabb2efc4'::uuid, '01a91b1c-2917-5847-9ac9-a51ab7f97123'::uuid, 'general-speaking-beginner-01-one-clear-point', 'One clear point', 'State one main point before adding support.', 1, false, '4d4604d0-fe19-51cb-8a3f-0291d0a72e44'::uuid, true),
  ('928899ab-6f86-5f08-9db8-6eb0d54e63bc'::uuid, '01a91b1c-2917-5847-9ac9-a51ab7f97123'::uuid, 'general-speaking-beginner-02-concrete-details', 'Concrete details', 'Use specific details to make an idea easy to picture.', 2, false, 'b927c0b7-05ae-508f-bba3-763e71cc33d1'::uuid, true),
  ('52badc45-9c7c-55d9-969b-450daaf47e1a'::uuid, '01a91b1c-2917-5847-9ac9-a51ab7f97123'::uuid, 'general-speaking-beginner-03-explain-a-simple-process', 'Explain a simple process', 'Present familiar steps in a usable order.', 3, false, '4b977408-fab6-50cf-bd42-1eae5e2a5ba2'::uuid, true),
  ('ae67908d-1a01-5f08-b32b-d727e7750f1e'::uuid, '01a91b1c-2917-5847-9ac9-a51ab7f97123'::uuid, 'general-speaking-beginner-04-give-a-reason', 'Give a reason', 'Connect a clear claim to a relevant reason.', 4, false, 'a66de8e5-5c12-5778-8456-a3fc4b5e2446'::uuid, true),
  ('7b9fcd61-d6ff-5f9c-bec7-1c86071b8486'::uuid, '01a91b1c-2917-5847-9ac9-a51ab7f97123'::uuid, 'general-speaking-beginner-05-sequence-a-short-story', 'Sequence a short story', 'Order a brief event with a beginning, change, and ending.', 5, false, 'b2e65c7c-7ac8-5f4b-aed7-d5d5d651730f'::uuid, true),
  ('729bbc58-253e-5998-a535-a5dbf409bf7f'::uuid, '01a91b1c-2917-5847-9ac9-a51ab7f97123'::uuid, 'general-speaking-beginner-06-summarize-something', 'Summarize something', 'Reduce familiar material to its essential idea.', 6, false, '2205350b-d88a-5b0b-805c-6cc1a18fe25a'::uuid, true),
  ('12219d2c-367d-5280-a3af-5ef10ba18a25'::uuid, '01a91b1c-2917-5847-9ac9-a51ab7f97123'::uuid, 'general-speaking-beginner-07-compare-two-options', 'Compare two options', 'Compare options using the same practical criteria.', 7, false, '6303ce9d-c696-58de-a171-f68ab6daa694'::uuid, true),
  ('a4d5edc8-4006-5aee-b81d-9e5bcbff7bf6'::uuid, '01a91b1c-2917-5847-9ac9-a51ab7f97123'::uuid, 'general-speaking-beginner-08-state-a-preference', 'State a preference', 'Choose between options and support the preference.', 8, false, 'f5b74854-aa5d-5afe-afd1-0eafdf8500f1'::uuid, true),
  ('f74cd6e1-8985-58c1-afb0-b34d7ef25516'::uuid, '01a91b1c-2917-5847-9ac9-a51ab7f97123'::uuid, 'general-speaking-beginner-09-end-concisely', 'End concisely', 'Close a response by restating the main takeaway without repeating everything.', 9, false, '7476624d-6ddf-5096-9831-1d09430f6e80'::uuid, true),
  ('899abec6-57c8-5efa-8a38-afca26d51bcd'::uuid, '01a91b1c-2917-5847-9ac9-a51ab7f97123'::uuid, 'general-speaking-beginner-10-checkpoint', 'Clear everyday response checkpoint', 'Combine a clear point, concrete support, logical order, and a concise ending.', 10, true, '52a7eb6f-547f-5b74-9639-5f31a9e14ccf'::uuid, true),
  ('a47c1952-af89-5e92-b59f-3a7913d33813'::uuid, 'de91f607-714a-5980-9a7e-0a8dcb702aa0'::uuid, 'general-speaking-intermediate-01-explain-an-unfamiliar-idea', 'Explain an unfamiliar idea', 'Define an idea for a listener without assuming shared context.', 1, false, 'a94b7a52-dce7-5993-97b6-648c8b175293'::uuid, true),
  ('12503f90-fa7e-5e97-a1c8-99c746f9d283'::uuid, 'de91f607-714a-5980-9a7e-0a8dcb702aa0'::uuid, 'general-speaking-intermediate-02-build-a-three-part-answer', 'Build a three-part answer', 'Organize one response into three distinct supporting points.', 2, false, '587aa5c4-c153-5d22-a97a-f5bcd3b22628'::uuid, true),
  ('a286f3ae-d9dd-5492-81f7-b0be42125234'::uuid, 'de91f607-714a-5980-9a7e-0a8dcb702aa0'::uuid, 'general-speaking-intermediate-03-support-an-opinion-with-an-example', 'Support an opinion with an example', 'Use a specific example as evidence for an opinion.', 3, false, '1db55afa-1b2a-5ad2-b627-b67ef44bcfc7'::uuid, true),
  ('12dd4ac9-9c7a-5f2d-9a83-a6b51be60a67'::uuid, 'de91f607-714a-5980-9a7e-0a8dcb702aa0'::uuid, 'general-speaking-intermediate-04-adapt-to-a-listener', 'Adapt to a listener', 'Adjust context and detail for a particular listener.', 4, false, '622fe79c-4238-530e-bd19-aba07bbfc080'::uuid, true),
  ('64139d73-bdd6-510a-ae3e-0963ef71d111'::uuid, 'de91f607-714a-5980-9a7e-0a8dcb702aa0'::uuid, 'general-speaking-intermediate-05-handle-a-follow-up', 'Handle a follow-up', 'Extend an answer directly when a listener asks for more detail.', 5, false, '84da0ba0-aec5-5836-8923-cb3fcffa190d'::uuid, true),
  ('0bb3992d-43e8-576a-a2a6-b7ab134e3037'::uuid, 'de91f607-714a-5980-9a7e-0a8dcb702aa0'::uuid, 'general-speaking-intermediate-06-clarify-a-vague-point', 'Clarify a vague point', 'Replace a broad statement with precise meaning and an example.', 6, false, '3b2e18d7-038d-5a7a-b66f-6c64dfc498b7'::uuid, true),
  ('271850ab-0f61-51eb-85ed-a5f3f6a2f836'::uuid, 'de91f607-714a-5980-9a7e-0a8dcb702aa0'::uuid, 'general-speaking-intermediate-07-explain-cause-and-effect', 'Explain cause and effect', 'Connect an action to its likely consequences without overstating certainty.', 7, false, '4f757680-24b7-55ee-9413-77f1a45a8599'::uuid, true),
  ('f57f72db-cec3-5ebd-8844-76628a64297c'::uuid, 'de91f607-714a-5980-9a7e-0a8dcb702aa0'::uuid, 'general-speaking-intermediate-08-balance-two-sides', 'Balance two sides', 'Present competing benefits before reaching a position.', 8, false, 'd0da3070-0b71-523f-8b1c-ec6f804acc85'::uuid, true),
  ('fd893a8a-e139-510a-9d9c-e623fcac76c6'::uuid, 'de91f607-714a-5980-9a7e-0a8dcb702aa0'::uuid, 'general-speaking-intermediate-09-answer-within-a-tighter-limit', 'Answer within a tighter limit', 'Prioritize essential information under a short time limit.', 9, false, '0ee553d7-5931-55a3-a312-73cd15c607a8'::uuid, true),
  ('ee5c6430-01a9-5dbe-8ed1-1b3eabcfdb79'::uuid, 'de91f607-714a-5980-9a7e-0a8dcb702aa0'::uuid, 'general-speaking-intermediate-10-checkpoint', 'Structured explanation checkpoint', 'Combine audience context, a clear structure, evidence, tradeoffs, and a concise close.', 10, true, 'c1adb0e4-4915-59de-b324-854b6f974be0'::uuid, true),
  ('3d32df18-d178-59dd-ae2f-9770a34fd27a'::uuid, '3d9b2e73-c170-55cf-8ff1-f549971c5ea7'::uuid, 'general-speaking-advanced-01-frame-an-ambiguous-topic', 'Frame an ambiguous topic', 'Define the useful scope of a broad or ambiguous question.', 1, false, '1fc82d35-6704-540b-b782-aa1b8d50a570'::uuid, true),
  ('b3357950-c9ba-5db5-8d17-dd75a6fe01dc'::uuid, '3d9b2e73-c170-55cf-8ff1-f549971c5ea7'::uuid, 'general-speaking-advanced-02-synthesize-several-points', 'Synthesize several points', 'Connect several observations into one coherent conclusion.', 2, false, '39d995ad-c5cf-5bfd-843d-ed6b859e6975'::uuid, true),
  ('8b850ae7-f0fc-59ba-aace-08bbe16cd9f3'::uuid, '3d9b2e73-c170-55cf-8ff1-f549971c5ea7'::uuid, 'general-speaking-advanced-03-make-a-nuanced-case', 'Make a nuanced case', 'State a position with conditions and limits instead of treating it as absolute.', 3, false, '9b7b52b5-a8b9-53c9-99b2-2d0c0d5a3409'::uuid, true),
  ('2ad82ebb-9534-5cd5-8e45-22f55b0b57c5'::uuid, '3d9b2e73-c170-55cf-8ff1-f549971c5ea7'::uuid, 'general-speaking-advanced-04-respond-to-a-challenge', 'Respond to a challenge', 'Address a reasonable objection while preserving the main point.', 4, false, '818ed8ae-ea25-51c7-b9bf-e90a691cae2d'::uuid, true),
  ('8ae0ff50-9e63-58ed-a209-dadda243b4f1'::uuid, '3d9b2e73-c170-55cf-8ff1-f549971c5ea7'::uuid, 'general-speaking-advanced-05-prioritize-under-constraints', 'Prioritize under constraints', 'Choose what matters most when time or resources are limited.', 5, false, '5e87a394-6035-55f5-912f-0d25acc87d66'::uuid, true),
  ('1988845f-6d0c-5c86-93ea-0cffdb9cc39a'::uuid, '3d9b2e73-c170-55cf-8ff1-f549971c5ea7'::uuid, 'general-speaking-advanced-06-explain-tradeoffs', 'Explain tradeoffs', 'Describe what is gained and given up by a choice.', 6, false, 'cb6bfa56-3e1f-5812-994c-611b1fd4693b'::uuid, true),
  ('02f726bc-d27c-5472-bfc0-5563fdcd16af'::uuid, '3d9b2e73-c170-55cf-8ff1-f549971c5ea7'::uuid, 'general-speaking-advanced-07-reframe-mid-response', 'Reframe mid-response', 'Narrow or redirect an answer when the original framing is not useful.', 7, false, '52865d99-2167-5bce-868c-9e22ad0833bc'::uuid, true),
  ('c55d1547-84d8-5e55-8be9-19b590899b1c'::uuid, '3d9b2e73-c170-55cf-8ff1-f549971c5ea7'::uuid, 'general-speaking-advanced-08-deliver-a-concise-summary', 'Deliver a concise summary', 'Compress a complex explanation without losing the decision or rationale.', 8, false, '7edd637d-96f5-5527-9432-80610278eab5'::uuid, true),
  ('b81dfd6f-9781-5de8-baf0-c7dee1c88f12'::uuid, '3d9b2e73-c170-55cf-8ff1-f549971c5ea7'::uuid, 'general-speaking-advanced-09-combine-story-evidence-and-conclusion', 'Combine story, evidence, and conclusion', 'Use a brief experience as evidence that leads to a supported conclusion.', 9, false, '5652c3ce-adf8-57ab-9e68-ecc373a50f2e'::uuid, true),
  ('d0386501-2f47-5307-a5f9-4b0d64725dbb'::uuid, '3d9b2e73-c170-55cf-8ff1-f549971c5ea7'::uuid, 'general-speaking-advanced-10-checkpoint', 'Complex spontaneous response checkpoint', 'Frame ambiguity, synthesize considerations, address a challenge, and close decisively.', 10, true, 'e336b9c0-9ae1-53e3-bace-72dcf9263bbd'::uuid, true),
  ('b958a6c9-d1d3-551a-b48e-47ab64fa63c2'::uuid, '28ff41ef-7c39-5413-ad1b-2c2f03910aa4'::uuid, 'interviews-beginner-01-tell-me-about-yourself', 'Tell me about yourself', 'Give a selective introduction tied to the current opportunity.', 1, false, 'a7cc61d3-17a1-511c-b374-522ad4d22b2e'::uuid, true),
  ('afa4ab37-1f37-50ea-bebb-5c8a5b3eb98f'::uuid, '28ff41ef-7c39-5413-ad1b-2c2f03910aa4'::uuid, 'interviews-beginner-02-explain-your-motivation', 'Explain your motivation', 'Name a specific source of interest and connect it to the opportunity.', 2, false, '0ec7e147-3ef5-53dc-bc5b-ffe545fdfbf7'::uuid, true),
  ('ea21a934-d775-55fc-af89-a98e6dd9ac92'::uuid, '28ff41ef-7c39-5413-ad1b-2c2f03910aa4'::uuid, 'interviews-beginner-03-describe-a-strength', 'Describe a strength', 'Identify one relevant strength and show how it appears in action.', 3, false, 'c8886933-4e26-5ccd-9fb4-2bc53365acbd'::uuid, true),
  ('2a638e02-53e4-53b8-baa3-256afb7f85bd'::uuid, '28ff41ef-7c39-5413-ad1b-2c2f03910aa4'::uuid, 'interviews-beginner-04-discuss-a-growth-area', 'Discuss a growth area', 'Describe a current development area and the concrete action you take.', 4, false, '934694fc-1824-59a5-bded-a241aac818e5'::uuid, true),
  ('ad257015-1e38-523d-bf4b-5f9da04c0cbd'::uuid, '28ff41ef-7c39-5413-ad1b-2c2f03910aa4'::uuid, 'interviews-beginner-05-give-a-simple-example', 'Give a simple example', 'Support a claim with a brief relevant situation and outcome.', 5, false, '60377840-c060-5ecd-aa20-697261555c34'::uuid, true),
  ('a578b2ed-642a-518e-8cc9-55771cfa71c0'::uuid, '28ff41ef-7c39-5413-ad1b-2c2f03910aa4'::uuid, 'interviews-beginner-06-explain-a-success', 'Explain a success', 'Describe your contribution and the result without exaggeration.', 6, false, 'b683c6c8-2b0a-5bca-b7f3-9817151c93e9'::uuid, true),
  ('f7a6d160-1ea0-5dac-884e-a8bfd0615578'::uuid, '28ff41ef-7c39-5413-ad1b-2c2f03910aa4'::uuid, 'interviews-beginner-07-explain-a-challenge', 'Explain a challenge', 'Present a difficulty, your response, and what happened next.', 7, false, '3870346a-eee7-5dba-9c19-fdbbc8a240e9'::uuid, true),
  ('1d6ec1a2-d92c-5735-8f63-a3c84e72790b'::uuid, '28ff41ef-7c39-5413-ad1b-2c2f03910aa4'::uuid, 'interviews-beginner-08-why-this-role', 'Why this role', 'Connect your interests and abilities to the role itself.', 8, false, '95be339a-0492-5f5f-bb67-c67c16001afb'::uuid, true),
  ('919a43d0-1b1c-57d1-abf8-4cf6590f8d29'::uuid, '28ff41ef-7c39-5413-ad1b-2c2f03910aa4'::uuid, 'interviews-beginner-09-why-this-organization', 'Why this organization', 'Connect specific known qualities of a group to your motivation.', 9, false, 'ed481384-44da-5b04-a4f5-98cda11df1d2'::uuid, true),
  ('3fe7628d-0106-52ff-af45-d4d563fa7c3e'::uuid, '28ff41ef-7c39-5413-ad1b-2c2f03910aa4'::uuid, 'interviews-beginner-10-checkpoint', 'Beginner interview checkpoint', 'Combine a focused introduction, motivation, evidence, and a clear fit statement.', 10, true, 'e5ed3d25-dc59-5ed8-85c1-2acc15268718'::uuid, true),
  ('02721aff-71c0-50fb-bee6-ec318286a874'::uuid, '8bc34d1e-4ab0-527d-97f9-60da78113f86'::uuid, 'interviews-intermediate-01-behavioral-storytelling', 'Behavioral storytelling', 'Structure a past example around context, action, and result.', 1, false, '81cb28b8-c013-5fc6-9a84-e72d8c2b64b3'::uuid, true),
  ('0f4d2e9c-f5b4-5b11-8630-1160646e0647'::uuid, '8bc34d1e-4ab0-527d-97f9-60da78113f86'::uuid, 'interviews-intermediate-02-discuss-a-setback', 'Discuss a setback', 'Explain a setback honestly and focus on the response and learning.', 2, false, '6e9e2291-c35f-5ac4-aecc-765bbb32f01b'::uuid, true),
  ('97401b17-6b79-5647-808d-469dcbece380'::uuid, '8bc34d1e-4ab0-527d-97f9-60da78113f86'::uuid, 'interviews-intermediate-03-handle-conflict', 'Handle conflict', 'Describe disagreement through concrete actions and resolution.', 3, false, '25b0da5c-71c9-5d13-b3ed-06a170a400d2'::uuid, true),
  ('578a9b0b-419c-506a-988f-4c021bf261fc'::uuid, '8bc34d1e-4ab0-527d-97f9-60da78113f86'::uuid, 'interviews-intermediate-04-show-leadership', 'Show leadership', 'Explain how you helped others move toward a useful outcome.', 4, false, '1fc6ac9f-35d4-5f0e-aee5-6636ac3b91b0'::uuid, true),
  ('43ffc1bc-539f-5bb1-aa9d-091f6aa1b3b4'::uuid, '8bc34d1e-4ab0-527d-97f9-60da78113f86'::uuid, 'interviews-intermediate-05-explain-teamwork', 'Explain teamwork', 'Distinguish your contribution while showing how others contributed.', 5, false, 'fb465ebf-cb3d-512d-8588-7ed0e4facdb1'::uuid, true),
  ('ed7b98e2-b884-5da4-96fd-d5c940aa6846'::uuid, '8bc34d1e-4ab0-527d-97f9-60da78113f86'::uuid, 'interviews-intermediate-06-describe-a-difficult-decision', 'Describe a difficult decision', 'Explain the criteria and tradeoffs behind a decision.', 6, false, '110037dc-fef0-594d-854b-63d2ae908d6c'::uuid, true),
  ('d2362b43-ccde-5f5b-92bd-3c31fc31f52d'::uuid, '8bc34d1e-4ab0-527d-97f9-60da78113f86'::uuid, 'interviews-intermediate-07-show-initiative', 'Show initiative', 'Demonstrate noticing a need and acting with appropriate ownership.', 7, false, 'c6af51b9-747a-536d-ac38-351beec31c02'::uuid, true),
  ('9316381d-9edc-5a17-b1f0-0f9a5b76ec90'::uuid, '8bc34d1e-4ab0-527d-97f9-60da78113f86'::uuid, 'interviews-intermediate-08-explain-problem-solving', 'Explain problem solving', 'Make your reasoning process visible from diagnosis through result.', 8, false, '14f682a6-9b19-5f6f-9963-dd10361f2b25'::uuid, true),
  ('c57a4c7d-e53d-59b3-bd5c-d80773c0a5dc'::uuid, '8bc34d1e-4ab0-527d-97f9-60da78113f86'::uuid, 'interviews-intermediate-09-show-how-you-learn-quickly', 'Show how you learn quickly', 'Explain a learning strategy with evidence of application.', 9, false, '3b5c4141-14b8-5361-9ddb-4abdff699adc'::uuid, true),
  ('1f9b952f-4436-53d6-9959-5be1b6038316'::uuid, '8bc34d1e-4ab0-527d-97f9-60da78113f86'::uuid, 'interviews-intermediate-10-checkpoint', 'Intermediate interview checkpoint', 'Combine structured evidence, personal contribution, tradeoffs, and reflection.', 10, true, '08787b47-c1e3-5a73-9511-39ddfc2ffb1b'::uuid, true),
  ('7aad141d-f5cc-53f3-9c78-c070c727f462'::uuid, '2e4a5541-acf7-5820-b6a2-a89365861b58'::uuid, 'interviews-advanced-01-difficult-follow-up', 'Difficult follow-up', 'Answer a probing follow-up without abandoning the original evidence.', 1, false, '53e1ae15-bcb0-5a32-84c1-763713dc6486'::uuid, true),
  ('50350870-93a6-594b-bc11-53fdcedc1614'::uuid, '2e4a5541-acf7-5820-b6a2-a89365861b58'::uuid, 'interviews-advanced-02-ambiguous-behavioral-question', 'Ambiguous behavioral question', 'Clarify a broad question through the example and scope you choose.', 2, false, '0b9c987b-cb0c-54a2-bef1-71d5d38e5511'::uuid, true),
  ('c5ec563b-bb84-58b1-9a9f-d215237c6a27'::uuid, '2e4a5541-acf7-5820-b6a2-a89365861b58'::uuid, 'interviews-advanced-03-concise-high-level-answer', 'Concise high-level answer', 'Summarize complex experience for a listener who needs the main signal first.', 3, false, 'dac4500c-cdda-500b-9a26-3fdb0d041872'::uuid, true),
  ('2e0271fd-fc74-54a1-9dff-24ae9c71711d'::uuid, '2e4a5541-acf7-5820-b6a2-a89365861b58'::uuid, 'interviews-advanced-04-defend-a-decision', 'Defend a decision', 'Support a past choice while acknowledging reasonable alternatives.', 4, false, '92ebfe74-aaa3-5c24-ade8-7edfd08c0f6d'::uuid, true),
  ('6d977e32-7652-5a43-bfea-c68926799f8f'::uuid, '2e4a5541-acf7-5820-b6a2-a89365861b58'::uuid, 'interviews-advanced-05-handle-criticism', 'Handle criticism', 'Respond to critical feedback with specificity, action, and boundaries when needed.', 5, false, '191b475d-1db3-5f5b-9312-d4498415ee02'::uuid, true),
  ('1b1becac-0dfc-53fd-862f-13b1547d8319'::uuid, '2e4a5541-acf7-5820-b6a2-a89365861b58'::uuid, 'interviews-advanced-06-competing-priorities', 'Competing priorities', 'Explain prioritization criteria under simultaneous demands.', 6, false, '8563144c-9694-5cc2-a141-3b540ba9fc99'::uuid, true),
  ('9753c51a-0cc6-5d99-affc-890475806fee'::uuid, '2e4a5541-acf7-5820-b6a2-a89365861b58'::uuid, 'interviews-advanced-07-ethical-judgment', 'Ethical judgment', 'Explain a principled decision when convenience and responsibility conflict.', 7, false, '2f48a50d-6c7e-54b8-a8f1-76311f1b25aa'::uuid, true),
  ('75164233-68f2-5b13-9d6c-3cee32070b91'::uuid, '2e4a5541-acf7-5820-b6a2-a89365861b58'::uuid, 'interviews-advanced-08-strategic-thinking', 'Strategic thinking', 'Connect immediate action to longer-term effects and uncertainty.', 8, false, 'b2247cba-a8a0-5ebe-ac21-b1f53fb16e17'::uuid, true),
  ('967c9e5b-5d44-5b32-9212-5789279e595c'::uuid, '2e4a5541-acf7-5820-b6a2-a89365861b58'::uuid, 'interviews-advanced-09-pressure-question', 'Pressure question', 'Stay direct and measured when a question challenges readiness or fit.', 9, false, 'e5d6756b-6c01-56cd-8f00-9668ef902f6e'::uuid, true),
  ('d636b25d-fa38-52a1-bd58-46d226d2727e'::uuid, '2e4a5541-acf7-5820-b6a2-a89365861b58'::uuid, 'interviews-advanced-10-checkpoint', 'Advanced interview checkpoint', 'Synthesize complex evidence, defend judgment, address pressure, and remain concise.', 10, true, '9ab7da45-1853-5f72-a862-2b60d85a7995'::uuid, true),
  ('257706ad-6f84-5c94-8ffe-8a9856045bb5'::uuid, 'a041bbfd-83fa-5af1-923a-221aa7001ac2'::uuid, 'presentations-beginner-01-open-with-purpose', 'Open with purpose', 'Tell listeners immediately what the talk will help them understand or decide.', 1, false, 'ed0a8abc-e082-50fe-8080-379106547614'::uuid, true),
  ('d7aba375-0b59-5a80-9108-e74e9b812d1d'::uuid, 'a041bbfd-83fa-5af1-923a-221aa7001ac2'::uuid, 'presentations-beginner-02-state-one-main-idea', 'State one main idea', 'Center a short presentation on one explicit message.', 2, false, '3e810b61-f8ad-5f53-82ec-3f9346f7de8d'::uuid, true),
  ('3913f7e2-2f78-5527-9e41-afdb27586992'::uuid, 'a041bbfd-83fa-5af1-923a-221aa7001ac2'::uuid, 'presentations-beginner-03-explain-in-clear-steps', 'Explain in clear steps', 'Teach a familiar process with ordered, distinct steps.', 3, false, '2df0ffff-0f6b-56bd-afc4-28ac6464627e'::uuid, true),
  ('eb23d829-aa98-57cc-b9d7-c12cef8b7655'::uuid, 'a041bbfd-83fa-5af1-923a-221aa7001ac2'::uuid, 'presentations-beginner-04-use-a-concrete-example', 'Use a concrete example', 'Make an abstract point understandable through one specific example.', 4, false, '7be029a5-623c-5595-b622-3bfedc5265cb'::uuid, true),
  ('9d4d6379-e53c-5b04-84b5-f8c9f76993b5'::uuid, 'a041bbfd-83fa-5af1-923a-221aa7001ac2'::uuid, 'presentations-beginner-05-signpost-sections', 'Signpost sections', 'Use brief verbal cues to show how parts of a talk connect.', 5, false, '6d592902-0a4d-5069-8066-dcfe1eb25c37'::uuid, true),
  ('1ef699d2-0134-515b-a4f0-adc307a0b336'::uuid, 'a041bbfd-83fa-5af1-923a-221aa7001ac2'::uuid, 'presentations-beginner-06-summarize-the-key-point', 'Summarize the key point', 'Restate the essential message without replaying the full talk.', 6, false, '2ce5fe08-9a93-543d-8cf1-45efb4efc273'::uuid, true),
  ('d4e076f9-ef5b-5bf6-9c6a-62b33bc39a32'::uuid, 'a041bbfd-83fa-5af1-923a-221aa7001ac2'::uuid, 'presentations-beginner-07-make-a-recommendation', 'Make a recommendation', 'State a practical recommendation and the reason for it.', 7, false, '6b817d49-0d92-5838-b699-bc3e34f00c85'::uuid, true),
  ('5a937a62-ec54-5d32-afac-7df9cc5c51a9'::uuid, 'a041bbfd-83fa-5af1-923a-221aa7001ac2'::uuid, 'presentations-beginner-08-close-with-a-next-step', 'Close with a next step', 'End with a specific action the listener can take.', 8, false, 'b8f1e10c-818e-5623-8675-60097d8939fa'::uuid, true),
  ('7b86f811-f6f4-508d-bb80-7853c30b55f9'::uuid, 'a041bbfd-83fa-5af1-923a-221aa7001ac2'::uuid, 'presentations-beginner-09-fit-a-one-minute-limit', 'Fit a one-minute limit', 'Select and pace only the information that fits the available time.', 9, false, '36b7b7f8-016a-5282-b933-0308b5d8d99e'::uuid, true),
  ('8f487e4a-80b9-595a-9e6d-3c4f5f95e532'::uuid, 'a041bbfd-83fa-5af1-923a-221aa7001ac2'::uuid, 'presentations-beginner-10-checkpoint', 'Short structured talk checkpoint', 'Combine purpose, structure, an example, a recommendation, and a next step.', 10, true, '0c3e5ef1-80cf-521e-99ba-c0981e31b4e1'::uuid, true),
  ('af12d00f-4c5a-599a-8524-48c87fdd5257'::uuid, '5bf9d6cc-7fc7-56a0-9b5f-24a11e45a2aa'::uuid, 'presentations-intermediate-01-adapt-the-opening-to-an-audience', 'Adapt the opening to an audience', 'Choose an opening based on what a defined audience needs.', 1, false, '9f059f12-cab4-51db-a309-b2f5b718f804'::uuid, true),
  ('9f852901-3ca9-5792-8ac3-698aa1956185'::uuid, '5bf9d6cc-7fc7-56a0-9b5f-24a11e45a2aa'::uuid, 'presentations-intermediate-02-connect-evidence-to-a-claim', 'Connect evidence to a claim', 'Explain how an example or observation supports the main claim.', 2, false, 'b67cf730-6e20-5309-87ed-d56c2b3e6c49'::uuid, true),
  ('9e32e760-5add-5b46-a335-36356e03a7b3'::uuid, '5bf9d6cc-7fc7-56a0-9b5f-24a11e45a2aa'::uuid, 'presentations-intermediate-03-compare-two-options', 'Compare two options', 'Present alternatives through consistent decision criteria.', 3, false, 'ff1b6153-fb9c-52ed-966c-887a7e6629ef'::uuid, true),
  ('c3e246eb-969b-5dc1-abf5-243c77847a3f'::uuid, '5bf9d6cc-7fc7-56a0-9b5f-24a11e45a2aa'::uuid, 'presentations-intermediate-04-explain-a-trend', 'Explain a trend', 'Describe a pattern, likely causes, and limits without inventing certainty.', 4, false, 'b05446f2-952b-501f-a7de-459a80294742'::uuid, true),
  ('6a066b80-2312-52bd-adba-1d66f87efd79'::uuid, '5bf9d6cc-7fc7-56a0-9b5f-24a11e45a2aa'::uuid, 'presentations-intermediate-05-transition-between-ideas', 'Transition between ideas', 'Move between related points while preserving the throughline.', 5, false, '01a2fcf2-9ec0-51a1-be2b-76ac43098bdb'::uuid, true),
  ('70633e2f-9469-58cb-b9ac-daab96c83cc9'::uuid, '5bf9d6cc-7fc7-56a0-9b5f-24a11e45a2aa'::uuid, 'presentations-intermediate-06-anticipate-a-question', 'Anticipate a question', 'Address a likely listener concern before it interrupts the recommendation.', 6, false, 'de48a691-3738-534d-853a-580e8305f8ed'::uuid, true),
  ('54fed396-b212-5fa7-aa61-617da29ae559'::uuid, '5bf9d6cc-7fc7-56a0-9b5f-24a11e45a2aa'::uuid, 'presentations-intermediate-07-persuade-with-a-reason-and-example', 'Persuade with a reason and example', 'Support a requested action with both rationale and concrete evidence.', 7, false, '7c228f7c-cecb-55b1-ac29-366091f3d1e4'::uuid, true),
  ('e776ffa5-8ecc-56a9-907a-6f893ec115fd'::uuid, '5bf9d6cc-7fc7-56a0-9b5f-24a11e45a2aa'::uuid, 'presentations-intermediate-08-teach-a-process', 'Teach a process', 'Explain how to complete a task while highlighting decision points.', 8, false, '31847020-a72e-5d13-a2b9-53d341613f09'::uuid, true),
  ('88559658-59e5-52d3-8841-e8ef47c0b914'::uuid, '5bf9d6cc-7fc7-56a0-9b5f-24a11e45a2aa'::uuid, 'presentations-intermediate-09-defend-a-recommendation', 'Defend a recommendation', 'Explain why one proposal best fits the stated constraints.', 9, false, '8ceeac30-dfc0-5188-8531-c9b13efe6c16'::uuid, true),
  ('cdfd7b03-0701-54c5-bf44-ba13a13461db'::uuid, '5bf9d6cc-7fc7-56a0-9b5f-24a11e45a2aa'::uuid, 'presentations-intermediate-10-checkpoint', 'Persuasive presentation checkpoint', 'Combine audience adaptation, evidence, comparison, anticipation, and a defended recommendation.', 10, true, '193d0999-ebea-553e-acb8-1e75f406727f'::uuid, true),
  ('7844fd7b-14ba-510e-bb57-f37833ac2571'::uuid, 'fd24ea63-45d9-54a9-86e8-0f301f703e38'::uuid, 'presentations-advanced-01-frame-a-complex-issue', 'Frame a complex issue', 'Define the decision, scope, and relevant tensions before arguing a position.', 1, false, '95b9663a-91de-5dd1-add1-ae20699ab0ca'::uuid, true),
  ('a63e9ccb-0549-57a8-a63a-b5360c26060c'::uuid, 'fd24ea63-45d9-54a9-86e8-0f301f703e38'::uuid, 'presentations-advanced-02-synthesize-several-considerations', 'Synthesize several considerations', 'Combine distinct constraints into a coherent recommendation.', 2, false, '9b4a6172-9931-5c3e-b102-c591b075a346'::uuid, true),
  ('eade0ef4-e90d-5707-b85c-e48d02535e8b'::uuid, 'fd24ea63-45d9-54a9-86e8-0f301f703e38'::uuid, 'presentations-advanced-03-explain-tradeoffs', 'Explain tradeoffs', 'Make the benefits and costs of a proposal explicit.', 3, false, 'a3dfc26d-521e-5248-8af8-eea214a56770'::uuid, true),
  ('175448f4-64ee-53a6-89c6-42fab53f2fe9'::uuid, 'fd24ea63-45d9-54a9-86e8-0f301f703e38'::uuid, 'presentations-advanced-04-present-uncertainty-precisely', 'Present uncertainty precisely', 'Separate known information, assumptions, and possible outcomes.', 4, false, 'f9b13974-0d3c-5618-a0b3-33a544280662'::uuid, true),
  ('007281bb-23b1-5dbf-9333-37bd9c15ab65'::uuid, 'fd24ea63-45d9-54a9-86e8-0f301f703e38'::uuid, 'presentations-advanced-05-handle-a-skeptical-question', 'Handle a skeptical question', 'Respond directly to skepticism with evidence and appropriate limits.', 5, false, '8214effc-cdc4-50a9-afb3-58100effc01d'::uuid, true),
  ('d9892657-d30d-5466-8371-a1bc8496e6a8'::uuid, 'fd24ea63-45d9-54a9-86e8-0f301f703e38'::uuid, 'presentations-advanced-06-adjust-after-an-interruption', 'Adjust after an interruption', 'Resume or reshape a talk after a listener changes the available time or focus.', 6, false, 'aaacbb01-87d4-58f2-ac19-7e78e8e7195a'::uuid, true),
  ('2bec0191-5801-5024-81fb-89fcdbf50390'::uuid, 'fd24ea63-45d9-54a9-86e8-0f301f703e38'::uuid, 'presentations-advanced-07-make-a-strategic-recommendation', 'Make a strategic recommendation', 'Link a recommended first step to longer-term goals and constraints.', 7, false, 'fd41b428-f9d7-57ab-962a-e20f42e62049'::uuid, true),
  ('f273fab7-897a-5af7-a5f4-87f2a5ca74b2'::uuid, 'fd24ea63-45d9-54a9-86e8-0f301f703e38'::uuid, 'presentations-advanced-08-condense-a-complex-message', 'Condense a complex message', 'Preserve the decision and essential rationale while removing secondary detail.', 8, false, '9064ca93-5b2c-575b-9243-d6a7f3e4a686'::uuid, true),
  ('7ca56002-403d-5623-9683-e530f164b8ec'::uuid, 'fd24ea63-45d9-54a9-86e8-0f301f703e38'::uuid, 'presentations-advanced-09-close-with-a-clear-decision', 'Close with a clear decision', 'Turn analysis into an explicit decision, owner, or next action.', 9, false, '40ebe5a1-30df-5204-870d-b03bffdb830c'::uuid, true),
  ('6b575b56-6058-5c6a-8f8f-515d25d1d55c'::uuid, 'fd24ea63-45d9-54a9-86e8-0f301f703e38'::uuid, 'presentations-advanced-10-checkpoint', 'Advanced presentation checkpoint', 'Frame complexity, synthesize tradeoffs, handle skepticism, and close with a clear decision.', 10, true, 'e2c1b88d-057d-5867-b346-89591f794594'::uuid, true),
  ('a2a60b07-eb44-5ea5-a0dc-a45ecc94b906'::uuid, '1bb42270-06ab-51bd-b803-92cb97c26318'::uuid, 'conversations-beginner-01-start-with-a-clear-response', 'Start with a clear response', 'Answer the other person directly before adding context.', 1, false, '2cf9b0a5-af81-51d1-970f-7a6aacc4d311'::uuid, true),
  ('461ff81a-cf56-5861-8f5c-be9f368781da'::uuid, '1bb42270-06ab-51bd-b803-92cb97c26318'::uuid, 'conversations-beginner-02-ask-an-open-follow-up', 'Ask an open follow-up', 'Invite a fuller answer with a question that cannot be answered only yes or no.', 2, false, '7d2d98f1-05df-5850-91a4-5a18ef4549d5'::uuid, true),
  ('4c97d65d-7d49-5d6b-b1ab-c81053a6b621'::uuid, '1bb42270-06ab-51bd-b803-92cb97c26318'::uuid, 'conversations-beginner-03-show-you-understood', 'Show you understood', 'Reflect the relevant meaning before moving the conversation forward.', 3, false, '4a677b78-7c94-5270-94c9-2bc208458498'::uuid, true),
  ('62c8a56b-1679-520c-ba9c-4b24bf0cc11d'::uuid, '1bb42270-06ab-51bd-b803-92cb97c26318'::uuid, 'conversations-beginner-04-add-a-relevant-detail', 'Add a relevant detail', 'Contribute enough detail to continue the exchange without taking it over.', 4, false, 'b79aaa14-32a5-552f-b3f9-1d495b73e5a0'::uuid, true),
  ('728f83c3-975a-512e-bbc8-6398fe41331e'::uuid, '1bb42270-06ab-51bd-b803-92cb97c26318'::uuid, 'conversations-beginner-05-ask-for-clarification', 'Ask for clarification', 'Request the specific information needed to understand an unclear message.', 5, false, 'ffe19e04-ec1f-5831-b5d2-aa6c8e8a7658'::uuid, true),
  ('f1dd817c-e757-5939-a54f-964c547936b0'::uuid, '1bb42270-06ab-51bd-b803-92cb97c26318'::uuid, 'conversations-beginner-06-express-a-preference', 'Express a preference', 'State what you prefer while leaving room for the other person.', 6, false, 'f91c8caa-c8a4-56db-b9c6-1ade3567d87c'::uuid, true),
  ('edb2bb61-9ee4-58ef-ad79-806c8eaeafea'::uuid, '1bb42270-06ab-51bd-b803-92cb97c26318'::uuid, 'conversations-beginner-07-disagree-respectfully', 'Disagree respectfully', 'Name disagreement directly while recognizing the other perspective.', 7, false, '665c921b-18cf-548e-be8f-d51020043823'::uuid, true),
  ('e2bfea9d-2771-524e-828f-116a914052eb'::uuid, '1bb42270-06ab-51bd-b803-92cb97c26318'::uuid, 'conversations-beginner-08-give-specific-feedback', 'Give specific feedback', 'Describe an observable behavior and its effect instead of judging the person.', 8, false, 'cc33cf11-a48b-5699-845b-6575c2d2dd23'::uuid, true),
  ('7c94e8cc-680f-5058-9a36-12323c63a6f0'::uuid, '1bb42270-06ab-51bd-b803-92cb97c26318'::uuid, 'conversations-beginner-09-close-clearly', 'Close clearly', 'End an exchange with a shared understanding or next step.', 9, false, '150d3218-3823-52e9-9aab-bcdedcecd828'::uuid, true),
  ('d64b1ad9-94f1-5318-9140-ee71052f7914'::uuid, '1bb42270-06ab-51bd-b803-92cb97c26318'::uuid, 'conversations-beginner-10-checkpoint', 'Keep a short exchange moving checkpoint', 'Combine direct responses, listening, follow-up, respectful difference, and a clear close.', 10, true, '630730eb-9ec7-5ad9-ba9f-0ae2797c550e'::uuid, true),
  ('88e36dfd-f62b-58a9-b0e4-abd22f90dc47'::uuid, '20d4f3d1-4f73-546f-b17a-ec971eebc9e4'::uuid, 'conversations-intermediate-01-explore-another-point-of-view', 'Explore another point of view', 'Ask and respond in a way that reveals the reasoning behind a different view.', 1, false, 'b1641cfb-d50e-5c6c-a7af-a959d32bc4a9'::uuid, true),
  ('bf5d18ee-f5ec-5f5e-9580-13929e0c18bd'::uuid, '20d4f3d1-4f73-546f-b17a-ec971eebc9e4'::uuid, 'conversations-intermediate-02-clarify-a-misunderstanding', 'Clarify a misunderstanding', 'Correct the meaning without assigning blame or escalating tone.', 2, false, 'd6e9f951-5383-5128-8bb7-e71d95b97882'::uuid, true),
  ('f308815d-2a61-5aef-ac24-f6733ea9369b'::uuid, '20d4f3d1-4f73-546f-b17a-ec971eebc9e4'::uuid, 'conversations-intermediate-03-raise-a-concern', 'Raise a concern', 'Name a specific risk and invite discussion of it.', 3, false, '5725b326-272a-5490-9c1b-b56bac7698ec'::uuid, true),
  ('489c14b2-83a9-5666-9248-0c8d3f4f2d4a'::uuid, '20d4f3d1-4f73-546f-b17a-ec971eebc9e4'::uuid, 'conversations-intermediate-04-set-a-boundary', 'Set a boundary', 'State a limit, a brief reason, and what remains possible.', 4, false, '2808f5fa-9448-5bcd-a5d2-bd9fa7756edd'::uuid, true),
  ('b0fed366-1cbd-5425-9f32-2c4d764b86e7'::uuid, '20d4f3d1-4f73-546f-b17a-ec971eebc9e4'::uuid, 'conversations-intermediate-05-explain-a-decision', 'Explain a decision', 'Give the relevant reasoning behind a choice without over-defending it.', 5, false, '0c6b7ccf-8e0c-5f15-b642-1a3316c4798c'::uuid, true),
  ('d7948ec6-e5ab-5124-b563-ee6b6400b761'::uuid, '20d4f3d1-4f73-546f-b17a-ec971eebc9e4'::uuid, 'conversations-intermediate-06-handle-an-interruption', 'Handle an interruption', 'Acknowledge an interruption and return to the unfinished point calmly.', 6, false, 'a95c026c-5def-5f0a-a6a8-e462eb027cba'::uuid, true),
  ('b747f92f-43ef-59e6-8712-3348e2d7c8ef'::uuid, '20d4f3d1-4f73-546f-b17a-ec971eebc9e4'::uuid, 'conversations-intermediate-07-redirect-a-drifting-conversation', 'Redirect a drifting conversation', 'Bring an exchange back to its purpose without dismissing the new topic.', 7, false, '308c29f4-29fd-5a89-b572-ca87f06ad882'::uuid, true),
  ('56594e8d-9f58-5fef-8fca-f6ad4cb74a35'::uuid, '20d4f3d1-4f73-546f-b17a-ec971eebc9e4'::uuid, 'conversations-intermediate-08-exchange-feedback', 'Exchange feedback', 'Give concrete feedback and respond constructively to feedback in return.', 8, false, '824f102e-37bd-5427-bbea-9fb0c9494c56'::uuid, true),
  ('5e43379a-6b7c-5a45-b4ae-1d712049fc08'::uuid, '20d4f3d1-4f73-546f-b17a-ec971eebc9e4'::uuid, 'conversations-intermediate-09-find-a-practical-next-step', 'Find a practical next step', 'Turn unresolved discussion into a specific action both people can accept.', 9, false, '63cb9944-6463-5569-ae70-47a4f8493af3'::uuid, true),
  ('524b48e9-98f5-5bb8-9b1d-d82e47660eeb'::uuid, '20d4f3d1-4f73-546f-b17a-ec971eebc9e4'::uuid, 'conversations-intermediate-10-checkpoint', 'Resolve a shared issue checkpoint', 'Combine listening, clarification, boundaries, feedback, and a workable next step.', 10, true, 'a86e5795-424a-5a11-a422-f4ba32f028d2'::uuid, true),
  ('304178ba-956e-58eb-8f0e-01eeb304864a'::uuid, 'a1509f08-224c-5a38-964e-fc4a378bd71f'::uuid, 'conversations-advanced-01-navigate-competing-needs', 'Navigate competing needs', 'Acknowledge multiple legitimate needs and look for a workable decision.', 1, false, '721e3667-31ad-5dfe-969e-feafed8a1815'::uuid, true),
  ('841e2d44-8e52-58db-9202-5703b9a2c443'::uuid, 'a1509f08-224c-5a38-964e-fc4a378bd71f'::uuid, 'conversations-advanced-02-discuss-a-sensitive-topic', 'Discuss a sensitive topic', 'Raise a personal or delicate concern with specific, nonjudgmental language.', 2, false, 'dff94412-6fd3-53b3-af16-e8dd77712a8d'::uuid, true),
  ('4d694c6d-0a82-55a1-96a3-f2b2b4eb7aa8'::uuid, 'a1509f08-224c-5a38-964e-fc4a378bd71f'::uuid, 'conversations-advanced-03-respond-to-defensiveness', 'Respond to defensiveness', 'Keep the issue specific when the other person feels accused.', 3, false, '64393e77-cd2a-518f-9d37-6cfc2ed2c9ee'::uuid, true),
  ('faf991e5-aac3-54a2-a82a-c9414c599bd8'::uuid, 'a1509f08-224c-5a38-964e-fc4a378bd71f'::uuid, 'conversations-advanced-04-de-escalate-disagreement', 'De-escalate disagreement', 'Lower tension while keeping the real disagreement available for resolution.', 4, false, '7e5e3d2f-7ef3-58af-b0a8-e83744e91e38'::uuid, true),
  ('bf836b18-345c-509c-8f0d-fae559e92a85'::uuid, 'a1509f08-224c-5a38-964e-fc4a378bd71f'::uuid, 'conversations-advanced-05-ask-about-an-unclear-concern', 'Ask about an unclear concern', 'Invite specificity when someone signals a problem indirectly.', 5, false, 'b2f3b47b-f142-5950-9d2c-6513f0fc71f0'::uuid, true),
  ('ca24d83a-66a5-55e8-aaf4-04c831af75fd'::uuid, 'a1509f08-224c-5a38-964e-fc4a378bd71f'::uuid, 'conversations-advanced-06-negotiate-a-boundary', 'Negotiate a boundary', 'Hold a necessary limit while discussing how it can work for both people.', 6, false, '0c0e91f2-0cfb-54eb-b2c8-ba8b633fbdd1'::uuid, true),
  ('fd2c70b6-6059-5cc9-82af-1d5143e31c7d'::uuid, 'a1509f08-224c-5a38-964e-fc4a378bd71f'::uuid, 'conversations-advanced-07-repair-after-a-misstatement', 'Repair after a misstatement', 'Correct wording, acknowledge its effect, and restate the intended meaning.', 7, false, '8ed01fa7-9a4f-50ac-8928-71a4b40da74f'::uuid, true),
  ('5ac001ba-4815-5296-90e5-e5c4cc917d0a'::uuid, 'a1509f08-224c-5a38-964e-fc4a378bd71f'::uuid, 'conversations-advanced-08-hold-a-nuanced-disagreement', 'Hold a nuanced disagreement', 'Express partial agreement and a meaningful difference without flattening either.', 8, false, 'a243c8f6-b613-5562-b384-2e38f536d784'::uuid, true),
  ('2327bbe8-c05b-55fe-bc08-b5fec6145649'::uuid, 'a1509f08-224c-5a38-964e-fc4a378bd71f'::uuid, 'conversations-advanced-09-reach-closure-without-full-agreement', 'Reach closure without full agreement', 'End a discussion with clarity about differences and next actions.', 9, false, 'a3796e7c-165f-5320-b70f-40bb814fc39d'::uuid, true),
